import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

public class SortingDemonstration {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>(List.of("Charlie", "Alice", "Bob"));

        // Approach 1: In-place collection sorting (Mutates the original list)
        names.sort(Comparator.naturalOrder());
        System.out.println("In-place sorted: " + names);

        // Approach 2: Stream sorted() (Produces a new immutable list, source untouched)
        List<String> unsortedNames = List.of("Zack", "Xavier", "Yara");
        List<String> sortedViaStream = unsortedNames.stream()
            .sorted(Comparator.reverseOrder())
            .collect(Collectors.toList());

        System.out.println("Source after stream: " + unsortedNames);
        System.out.println("Stream sorted result: " + sortedViaStream);
    }
}
